<?php
/** TEMP PS S1643 H2 — istorijos papildymas 12004-12106 (be atsauktu) + 11999-12003 statusai. D=dry, A=apply. */
add_action('init', function(){
  if (!isset($_GET['ps_s1643h2'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_s1643h2'])); $o=array('v'=>'S1643 H2','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280); ini_set('memory_limit','512M');
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $d=json_decode(gzdecode(base64_decode('')),true);
  if(!$d){ $o['klaida']='payload'; header('Content-Type: application/json'); echo json_encode($o); exit; }

  $sk=$wpdb->get_results("SELECT pm.meta_value sku, pm.post_id FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id AND po.post_type IN('product','product_variation') AND po.post_status<>'trash' WHERE pm.meta_key='_sku' AND pm.meta_value<>''");
  $map=array(); foreach($sk as $r) $map[trim((string)$r->sku)]=(int)$r->post_id;
  $tit=array(); foreach($wpdb->get_results("SELECT ID,post_title FROM {$p}posts WHERE post_type='product' AND post_status='publish'") as $r) $tit[mb_strtolower(trim(html_entity_decode($r->post_title)))]=(int)$r->ID;

  $rt=function($l) use($map,$tit){
    $m=trim((string)$l['modelis']);
    if($m!=='' && isset($map[$m])) return array($map[$m],'sku');
    $t=mb_strtolower(trim(html_entity_decode((string)$l['pav'])));
    if($t!=='' && isset($tit[$t])) return array($tit[$t],'pavadinimas');
    return array(null,'');
  };

  $esami=array_map('intval',$wpdb->get_col("SELECT id FROM {$p}ps_ist_uzsakymai WHERE id>=11990"));
  $st=array('nauji'=>0,'jau_yra'=>0,'eil'=>0,'sku'=>0,'pavadinimas'=>0,'nesusieta'=>0,'suma'=>0);
  $ne=array();
  foreach($d['u'] as $u){ if(in_array((int)$u['id'],$esami,true)){ $st['jau_yra']++; continue; } $st['nauji']++; $st['suma']+=(float)$u['suma']; }
  foreach($d['l'] as $l){ $st['eil']++; list($pid,$sus)=$rt($l);
    if($sus==='sku') $st['sku']++; elseif($sus==='pavadinimas') $st['pavadinimas']++; else { $st['nesusieta']++; if(count($ne)<40) $ne[$l['modelis']]=mb_substr($l['pav'],0,42); } }
  $st['suma']=round($st['suma'],2);
  $o['statistika']=$st; $o['nesusieti']=$ne;

  if($f==='A'){
    $iv=array('Užsakymas išsiųstas'=>1,'+Užsakymas išsiųstas+'=>1,'Mokėjimas gautas'=>1,'Užsakymas paruoštas'=>1);
    $ins=0; foreach($d['u'] as $u){ if(in_array((int)$u['id'],$esami,true)) continue;
      $wpdb->insert("{$p}ps_ist_uzsakymai",array('id'=>(int)$u['id'],'data'=>$u['data'],'email'=>$u['email'],'vardas'=>$u['vardas'],'pavarde'=>$u['pavarde'],'tel'=>$u['tel'],'imone'=>$u['imone'],'siuntimas'=>$u['siuntimas'],'miestas'=>$u['miestas'],'apmokejimas'=>$u['apmokejimas'],'suma_be'=>$u['suma_be'],'suma'=>$u['suma'],'statusas'=>$u['statusas'],'ivykdytas'=>isset($iv[$u['statusas']])?1:0,'saskaita'=>$u['saskaita'],'eiluciu'=>(int)$u['eiluciu']));
      $ins++; }
    $eins=0; foreach($d['l'] as $l){ if(in_array((int)$l['o'],$esami,true)) continue;
      list($pid,$sus)=$rt($l);
      $wpdb->insert("{$p}ps_ist_eilutes",array('uzsakymo_id'=>(int)$l['o'],'modelis'=>$l['modelis'],'pavadinimas'=>$l['pav'],'variantas'=>$l['var'],'kiekis'=>(int)$l['kiekis'],'kaina'=>$l['kaina'],'suma'=>$l['suma'],'wc_product_id'=>$pid,'susiejimas'=>$sus));
      $eins++; }
    $upd=0; foreach($d['upd'] as $u){ $upd+=(int)$wpdb->update("{$p}ps_ist_uzsakymai",array('statusas'=>$u['statusas'],'ivykdytas'=>isset($iv[$u['statusas']])?1:0),array('id'=>(int)$u['id'])); }
    $o['irasyta']=array('uzsakymai'=>$ins,'eilutes'=>$eins,'atnaujinta'=>$upd);
    $o['po']=array(
      'uzs_n'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_ist_uzsakymai"),
      'eil_n'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_ist_eilutes"),
      'max_id'=>(int)$wpdb->get_var("SELECT MAX(id) FROM {$p}ps_ist_uzsakymai"),
      'max_data'=>$wpdb->get_var("SELECT MAX(data) FROM {$p}ps_ist_uzsakymai"),
      'be_tevo'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_ist_eilutes e LEFT JOIN {$p}ps_ist_uzsakymai u ON u.id=e.uzsakymo_id WHERE u.id IS NULL"),
      'eiluciu_nesutampa'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_ist_uzsakymai u WHERE u.id>12003 AND u.eiluciu<>(SELECT COUNT(*) FROM {$p}ps_ist_eilutes e WHERE e.uzsakymo_id=u.id)"),
      'ivykdyti_suma'=>$wpdb->get_var("SELECT ROUND(SUM(suma),2) FROM {$p}ps_ist_uzsakymai WHERE ivykdytas=1"));
  }
  $o['ping']=wp_remote_retrieve_response_code(wp_remote_get(home_url('/'),array('timeout'=>30,'sslverify'=>false)));
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
},99);
